ex.solution:
import math

def farbabstand(a, b):
    return math.sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2)

print(farbabstand([200, 40, 40], [190, 30, 40]))
print(farbabstand([0, 0, 0], [255, 255, 255]))

